Instance.ref.Members:
var probe1: PlaygroundPoints^ = null;
var probe2: PlaygroundPoints^ = null;
var childProbe: PlaygroundPoints^ = null;
var child: demo::TestWindow* = null;
var touchingWindow: demo::TouchingInspection* = null;

func Slots(points: const Point?[]): string
{
  var text = "";
  for (i in range[0, points.Count))
  {
    text = text & "," & (cast string i) & "=";
    if (var point: Point? = points[i])
    {
      text = text & (cast string point.x) & ":" & (cast string point.y);
    }
    else { text = text & "empty"; }
  }
  return text;
}

func TraceData(name: string, arguments: GuiPointEventArgs*): void
{
  trace.Data = trace.Data & name & ":" & (cast string arguments.sequenceId)
    & ":" & (cast string arguments.pointId) & ":" & (cast string arguments.activePointCount)
    & ":" & (cast string arguments.position.x) & "," & (cast string arguments.position.y)
    & ":source=" & (cast string (arguments.compositionSource == inner))
    & ":event=" & (cast string (arguments.eventSource == inner))
    & Slots(arguments.Points) & ";";
}

func TraceEnd(name: string, arguments: GuiPointSequenceEndedEventArgs*): void
{
  trace.Data = trace.Data & name & ":" & (cast string arguments.sequenceId)
    & ":" & (cast string arguments.accepted) & ":" & (cast string (cast UInt64 arguments.reason))
    & Slots(arguments.Points) & ";";
}

