Button.ev.Clicked-eval:
{
            if (self.child is null)
            {
              self.child = new demo::TestWindow*();
              self.child.Text = "Point Input Secondary";
              self.childProbe = new PlaygroundPoints^(self.child, destruction);
              self.child.Location = {x:{value:(self.Location.x.value + 100)} y:{value:(self.Location.y.value + 100)}};
            }
            self.child.ShowWithOwner(self);
          }

